import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

/*
 * llms.txt (https://llmstxt.org/) asks for a clean Markdown copy of a page at the same URL plus
 * index.md, announced by rel="alternate" type="text/markdown", and for rel="describedby" to the
 * llms.txt that covers the page. A page opts in with `outputs: [HTML, MARKDOWN]` (gdc-ui turns it
 * on for every page and section in [outputs]); the theme defines the MARKDOWN format.
 */

const here = dirname(fileURLToPath(import.meta.url));
const THEMES_DIR = resolve(here, "..", "..");
const HUGO = resolve(here, "..", "..", "..", "node_modules", ".bin", "hugo");
const BASE_URL = "https://example.com/docs/";

function write(path, body) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, body);
}

function buildFixture() {
    const site = mkdtempSync(join(tmpdir(), "markdown-output-site-"));
    write(
        join(site, "hugo.toml"),
        `baseURL = "${BASE_URL}"
title = "Fixture docs"
themesDir = "${THEMES_DIR}"
theme = "gd-docs-theme-next"
disableKinds = ["taxonomy", "term", "rss", "sitemap"]
[params]
homeSlug = "latest"
[outputs]
home = ["HTML", "LLMS"]
section = ["HTML", "MARKDOWN"]
[outputFormats.LLMS]
mediaType = "text/plain"
baseName = "llms"
isPlainText = true
notAlternative = true
`,
    );
    for (const partial of ["css.html", "scripts.html", "footer.html"]) {
        write(join(site, "layouts", "_partials", partial), "");
    }
    write(join(site, "layouts", "index.llms.txt"), "# Fixture\n");
    const c = (rel, body) => write(join(site, "content", rel), body);
    c("latest/_index.md", "---\ntitle: Docs\n---\n");
    c("latest/api/_index.md", "---\ntitle: API\ndescription: Every symbol.\n---\n\nOne page per symbol.\n");
    c(
        "latest/api/pkg.foo.md",
        `---
title: IFoo
description: The foo props.
type: reference
source: api-documenter
kind: interface
stability: beta
outputs: [HTML, MARKDOWN]
---

<!-- Do not edit this file. It is automatically generated by API Documenter. -->

**Extends:** [IBar]({{< relref "/latest/api/pkg.bar.md" >}})\r\n\r\n\r\n\r\n**Signature:**\r\n
`,
    );
    c("latest/api/pkg.bar.md", "---\ntitle: IBar\ntype: reference\noutputs: [HTML, MARKDOWN]\n---\n\nBar.\n");
    c("latest/guide.md", "---\ntitle: Guide\n---\n\nA guide.\n");
    c(
        "latest/noted.md",
        `---
title: Noted
outputs: [HTML, MARKDOWN]
---

Intro.

{{% alert color="warning" title="Heads up" %}}
Line one.
Line two.
{{% /alert %}}

{{< figure src="/img/shot.png" alt="A screenshot" >}}
`,
    );

    const out = join(site, "public");
    execFileSync(HUGO, ["--source", site, "--destination", out, "--quiet"], { stdio: "pipe" });
    return out;
}

const out = buildFixture();
const head = (rel) => readFileSync(join(out, rel, "index.html"), "utf8").match(/<head>([\s\S]*?)<\/head>/)[1];

test("an opted-in page gets index.md next to index.html", () => {
    const md = readFileSync(join(out, "latest/api/pkg.foo/index.md"), "utf8");
    // a pointer to the index first, as Claude Code's docs do, then the title
    assert.match(md, /^> Documentation index: https:\/\/example\.com\/docs\/llms\.txt .*\n\n# IFoo\n/);
    assert.match(md, /^> The foo props\.$/m);
    assert.match(md, /^- Kind: interface\n- Stability: beta$/m);
    assert.doesNotMatch(md, /Do not edit this file/, "generator comments are dropped");
    assert.doesNotMatch(md, /\{\{</, "shortcodes are rendered");
    assert.doesNotMatch(md, /\n[ \t]*\n[ \t]*\n/, "no runs of blank lines");
    assert.doesNotMatch(md, /\r/, "LF line ends only");
    // A link to another page with a Markdown copy points at that copy, absolute: the file is read
    // outside the site.
    assert.match(md, /\[IBar\]\(https:\/\/example\.com\/docs\/latest\/api\/pkg\.bar\/index\.md\)/);
});

test("a page without the opt-in gets no Markdown copy", () => {
    assert.equal(existsSync(join(out, "latest/guide/index.md")), false);
});

test("the HTML page announces its Markdown copy and its llms.txt", () => {
    assert.match(
        head("latest/api/pkg.foo"),
        /<link rel="alternate" type="text\/markdown" href="https:\/\/example\.com\/docs\/latest\/api\/pkg\.foo\/index\.md">/,
    );
    assert.match(
        head("latest/guide"),
        /<link rel="describedby" href="https:\/\/example\.com\/docs\/llms\.txt">/,
    );
    assert.doesNotMatch(head("latest/guide"), /text\/markdown/);
});

test("a section's Markdown copy lists its pages, linked to their Markdown copies", () => {
    const md = readFileSync(join(out, "latest/api/index.md"), "utf8");
    assert.match(md, /\n# API\n\n> Every symbol\.\n\nOne page per symbol\.\n\n## Pages\n/);
    assert.match(
        md,
        /^- \[IFoo\]\(https:\/\/example\.com\/docs\/latest\/api\/pkg\.foo\/index\.md\): The foo props\.$/m,
    );
});

test("shortcodes come out as Markdown in the copy, not as HTML", () => {
    const md = readFileSync(join(out, "latest/noted/index.md"), "utf8");
    assert.match(md, /^> \*\*Heads up:\*\*\n> Line one\.\n> Line two\.$/m);
    assert.match(md, /^!\[A screenshot\]\(https:\/\/example\.com\/docs\/img\/shot\.png\)$/m);
    assert.doesNotMatch(md, /<div|<svg|<figure/);
});
